export const galaxyTypeArticles: StudyArticle[] = [
  { key: 'spiral', title: 'Spiral galaxies', deck: 'Repeated foundation slides in the mentor DSO decks', intro: 'Spirals combine a thin rotating disk, spiral density patterns, a central bulge, and a much larger halo. The classification describes visible structure, not a fixed evolutionary age.', mentorPriority: ['Disk, bulge, arms, halo, and central black hole', 'Young stars favor gas-rich arms', 'Old stars dominate the bulge and halo', 'Sa to Sd tracks arm winding and bulge prominence'], sections: [{ title: 'Structure and stellar populations', paragraphs: ['The disk contains most of the cold gas, dust, and active star formation. The bulge is thicker and contains older stars on less disk-like orbits. A faint halo holds old stars, globular clusters, and a dominant dark-matter component.', 'Spiral arms are density patterns. Gas entering a pattern compresses and forms stars, so the arms stay visible even though individual stars move through them.'], keyPoints: ['Tight arms and large bulge favor Sa', 'Loose fragmented arms and small bulge favor Sc or Sd', 'Face-on views reveal arms; edge-on views reveal disk thickness and dust'], examPrompt: 'Classify an Sa versus an Sc from bulge size, arm winding, and clumpiness.' }], sources: [{ label: 'NASA galaxy types', url: 'https://science.nasa.gov/universe/galaxies/types/' }] },
  { key: 'barred-spiral', title: 'Barred spiral galaxies', deck: 'Andromeda, Antennae, and NGC 4536 mentor decks', intro: 'A bar is an elongated stellar structure through the central region. It changes stellar and gas orbits and often channels gas toward rings or the nucleus.', mentorPriority: ['SB marks a strong bar; SAB marks an intermediate bar', 'Arms usually begin near the bar ends', 'About two-thirds of nearby spirals are barred', 'The Milky Way and Andromeda are barred'], sections: [{ title: 'Gas flow and recognition', paragraphs: ['A bar is not a solid rotating rod. It is an organized orbital pattern. Gravitational torques from the pattern move angular momentum and can direct gas inward.', 'On images, look for a straight central light distribution with arms emerging from its ends. Dust and inclination can conceal the bar, so near-infrared observations often reveal it more clearly.'], keyPoints: ['Near-IR penetrates dust and emphasizes old bar stars', 'Bars can feed circumnuclear rings and starbursts', 'SAB is not the same as SB'], examPrompt: 'Explain why NGC 4536’s weak bar is physically related to its central star-forming ring.' }], sources: [{ label: 'NASA Hubble tuning fork', url: 'https://science.nasa.gov/asset/hubble/the-hubble-tuning-fork-classification-of-galaxies/' }] },
  { key: 'elliptical', title: 'Elliptical galaxies', deck: 'Arp 147, M51, and Sombrero mentor decks', intro: 'Ellipticals appear smooth and range from nearly round E0 to elongated E7. They usually contain older stars, little cold gas, and weak current star formation.', mentorPriority: ['E0–E7 describes apparent ellipticity', 'Stellar orbits are not confined to a thin rotating disk', 'Old populations and many globular clusters are common', 'Major mergers can create elliptical remnants'], sections: [{ title: 'Shape, content, and formation', paragraphs: ['Elliptical galaxies lack the dust lanes and blue arm structure of spirals. Their stars move on a broad distribution of orbits, creating a three-dimensional spheroid.', 'The lack of cold molecular gas limits new star formation. Mergers can briefly supply gas and trigger star formation before the remnant settles into a smoother system.'], keyPoints: ['E7 is more elongated than E0', 'The sequence does not measure age', 'A smooth red appearance is evidence, not an absolute rule'], examPrompt: 'Why does the Antennae’s predicted future elliptical remnant still undergo intense star formation today?' }], sources: [{ label: 'NASA galaxy types', url: 'https://science.nasa.gov/universe/galaxies/types/' }] },
  { key: 'lenticular', title: 'Lenticular galaxies', deck: 'Arp 143 and M51 mentor decks', intro: 'Lenticulars, labeled S0, have a disk and bulge but no prominent spiral arms. Their structure resembles a spiral whose gas and arms have faded, while their stellar population resembles an elliptical.', mentorPriority: ['S0 sits at the fork between ellipticals and spirals', 'Disk present, large-scale arms absent', 'Little gas and little ongoing star formation', 'NGC 2444 and possibly NGC 5195 are relevant examples'], sections: [{ title: 'A disk without active arms', paragraphs: ['The key is to separate geometry from star formation. A lenticular can have a clear flattened disk while lacking the gas-rich arm pattern of a spiral.', 'Possible formation paths include gas stripping, exhausted star formation, and mergers. The tuning fork position does not prove one universal evolutionary path.'], keyPoints: ['Edge-on S0 galaxies can resemble ellipticals', 'Dust may still be present', 'Old stars do not erase the disk'], examPrompt: 'What observation would distinguish an edge-on lenticular from a true elliptical?' }], sources: [{ label: 'NASA lenticular example', url: 'https://science.nasa.gov/missions/hubble/a-galaxy-at-the-center-of-the-hubble-tuning-fork/' }] },
  { key: 'irregular-dwarf', title: 'Irregular and dwarf irregular galaxies', deck: 'M82 and NGC 1569 mentor decks', intro: 'Irregular galaxies do not fit the regular Hubble sequence. Some retain bars or partial structure, while others are strongly distorted by interactions. Dwarf irregulars are small, gas-rich, and often metal-poor.', mentorPriority: ['Irr I has some structure; Irr II is more chaotic', 'Sm retains spiral structure; Im does not', 'dIrr systems have low luminosity and often low metallicity', 'NGC 1569 is IBm; M82 only appears strongly irregular in optical light'], sections: [{ title: 'Classification without assuming cause', paragraphs: ['Irregular appearance can arise from low mass, patchy star formation, tidal disturbance, or obscuration. The label describes appearance and does not by itself identify which cause applies.', 'Dwarfs lose gas more easily because their escape speeds are low. This makes stellar feedback central to their evolution and metal enrichment.'], keyPoints: ['Irregular is not synonymous with interacting', 'A dwarf can have an intense specific star-formation rate', 'Infrared imaging may reveal hidden regular structure'], examPrompt: 'Contrast the reasons NGC 1569 and M82 appear irregular.' }], sources: [{ label: 'NASA galaxy types', url: 'https://science.nasa.gov/universe/galaxies/types/' }] },
  { key: 'interacting', title: 'Interacting and merging galaxies', deck: 'Antennae, Arp 143, Arp 147, Cartwheel, and M51 mentor decks', intro: 'Galaxy interactions range from flybys to minor and major mergers. Gravity distorts stellar orbits, while colliding gas clouds compress and often ignite star formation.', mentorPriority: ['Tidal tails and bridges diagnose interaction', 'Stars rarely collide directly', 'Gas responds dissipatively and can form stars', 'Major mergers combine similar-sized galaxies'], sections: [{ title: 'Reading the evidence', paragraphs: ['Tails form when tidal forces pull stars and gas outward. Bridges link the participants. Rings can form after a near head-on passage, while off-center passages often produce asymmetric arms and plumes.', 'Interactions can also drive gas inward, feeding central starbursts or an active nucleus. The outcome depends on mass ratio, geometry, gas content, and orbital energy.'], keyPoints: ['A flyby need not end in merger', 'Minor merger = unequal masses', 'Major merger = comparable masses', 'Morphological scars can outlive the closest passage'], examPrompt: 'Infer collision geometry from a tidal-tail system versus a symmetric expanding ring.' }], sources: [{ label: 'NASA Hubble galaxies', url: 'https://science.nasa.gov/mission/hubble/science/universe-uncovered/hubble-galaxies/' }] },
  { key: 'ring', title: 'Ring galaxies', deck: 'Arp 143, Arp 147, and Cartwheel mentor decks', intro: 'A collisional ring forms when a smaller galaxy passes through a disk and launches an expanding density wave. The ring glows because compressed gas forms short-lived massive stars.', mentorPriority: ['Bright blue ring = young massive stars', 'Original nucleus may sit off-center', 'Intruder may remain nearby', 'Arp 147 and Cartwheel are the clearest examples'], sections: [{ title: 'A wave rather than a material hoop', paragraphs: ['The outward-moving disturbance organizes where star formation occurs. Individual gas clouds and stars do not all travel outward at the same speed as one solid ring.', 'An off-center impact makes an asymmetric ring. A later encounter can distort a ring into a triangle, as in Arp 143.'], keyPoints: ['Look for age gradients across the ring', 'Compact X-ray binaries appear after massive stars die', 'Accretion can also make rings, so collision evidence matters'], examPrompt: 'What observation would support a collisional origin rather than a resonance or accretion ring?' }], sources: [{ label: 'NASA Cartwheel', url: 'https://www.nasa.gov/universe/webb-captures-stellar-gymnastics-in-the-cartwheel-galaxy/' }] },
  { key: 'starburst', title: 'Starburst galaxies', deck: 'M82, NGC 1569, NGC 4536, and MCG+07-33-027 mentor decks', intro: 'A starburst is a temporary physical state in which a galaxy forms stars fast enough to consume or disrupt its gas reservoir on a short timescale. It is not a Hubble morphology.', mentorPriority: ['Requires abundant cold gas plus a trigger', 'Mergers are common triggers but not required', 'Massive stars lead quickly to supernovae and winds', 'Feedback can quench the same burst'], sections: [{ title: 'Rates, triggers, and feedback', paragraphs: ['Compare star-formation rate with galaxy mass or area. NGC 1569’s total rate is smaller than a giant spiral’s, yet its rate per unit size is extreme.', 'Tidal compression triggers M82 and the Antennae. A weak bar may organize gas in NGC 4536. MCG+07-33-027 shows that an isolated galaxy can have a starburst whose trigger remains uncertain.'], keyPoints: ['H-alpha, UV, and infrared diagnose different parts of star formation', 'X-rays trace compact remnants and hot wind fluid', 'A starburst cannot continue indefinitely'], examPrompt: 'Choose the best star-formation tracer for unobscured young stars, ionized gas, and dust-hidden regions.' }], sources: [{ label: 'NASA galaxy glossary', url: 'https://science.nasa.gov/universe/glossary/' }] },
  { key: 'active-peculiar', title: 'Active, peculiar, and amorphous galaxies', deck: 'M51, Sombrero, and interaction mentor decks', intro: 'These labels answer different questions. AGN and LINER describe nuclear emission, while peculiar and amorphous describe unusual large-scale appearance.', mentorPriority: ['AGN energy comes from accretion onto a supermassive black hole', 'Seyfert and LINER are nuclear spectral classes', 'Pec marks morphology outside a normal sequence', 'A galaxy can carry both morphology and activity labels'], sections: [{ title: 'Keeping classifications separate', paragraphs: ['M51 is a spiral with a Seyfert-like active nucleus. Sombrero has a LINER nucleus. Their activity labels do not replace their structural classifications.', 'A peculiar or amorphous appearance can record tidal disturbance, merger history, or heavy dust. It does not automatically mean the nucleus is active.'], keyPoints: ['Accretion disks convert gravitational energy into radiation', 'Orientation and obscuration change how an AGN appears', 'Do not infer AGN solely from distorted shape'], examPrompt: 'Explain how one galaxy can simultaneously be SAB(rs)bc, starburst, and active.' }], sources: [{ label: 'NASA active galaxy types', url: 'https://science.nasa.gov/universe/galaxies/types/' }] },
];
